__version__ = "0.3.0"

"""The numbers a simple solid was made with, read back from its shape.

Draw a box 40 x 30 x 20, fillet some edges at 3, chamfer others at 2, drill
a hole of 6, and the solid forgets every number: what is left is faces.
They can be read back. The flat faces come in three square pairs and the
distance across each pair is a side. A fillet is a cylinder whose axis sits
its radius in from two sides, which names the edge it rounds; a chamfer is
a flat face cutting an edge at equal distances from both sides; a hole is a
cylinder square to a side, through the box or stopped by a flat floor. A
cylinder is a round side between two flat ends.

Rebuilt from those numbers, the solid must come out the same, or the shape
was something else and nothing is claimed about it. Because the numbers
come from the shape and not from a record of how it was built, this works
however the solid was drawn, filleted, moved, turned or imported. A changed
number rebuilds the solid with everything else as it was: a 3 mm fillet
stays 3 mm when the box grows, a hole stays where it is, and a blind hole
keeps its depth from the face it was drilled in.
"""


import itertools
from dataclasses import dataclass, field, replace

import numpy as np

from serpentine3d.core import occ

# how close two directions must be to count as one, and two lengths
_PARALLEL = 1 - 1e-7
_SQUARE = 1e-7
_REL = 1e-7
# how far a cutting tool reaches past the faces it cuts through
_MARGIN = 1.0


class NotRecognised(Exception):
    """The shape is none of the solids whose numbers can be read back."""


# --- the models -------------------------------------------------------------

@dataclass(frozen=True)
class Hole:
    """A round hole square to one side of a box.

    `through` holes run from side to side. A blind one enters on `side` (0
    or 1 along `axis`) and goes `depth` in. `point` is any point on its
    axis, in world coordinates: a hole stays where it is when the box
    around it changes."""
    axis: int
    point: tuple
    radius: float
    side: int = -1           # -1 for a hole that goes through
    depth: float = 0.0

    @property
    def through(self) -> bool:
        return self.side < 0


@dataclass(frozen=True)
class BoxModel:
    """A box, its fillets, chamfers and holes.

    `axes` are three unit vectors, right-handed; `origin` is the corner the
    box grows from and `size` its extent along each axis. A face of the box
    is (axis, side), side 0 at the origin and 1 across; an edge is the pair
    of its two faces, lower axis first. `fillets` and `chamfers` map an edge
    to its radius or distance."""
    origin: tuple
    axes: tuple
    size: tuple
    fillets: dict = field(default_factory=dict)
    chamfers: dict = field(default_factory=dict)
    holes: tuple = ()

    def resized(self, axis: int, value: float, anchor: float = 0.0):
        """The box `value` long along `axis`, everything else unchanged.

        `anchor` is the place that stays put, as a fraction of the old
        length from side 0: 0 holds side 0, 1 holds side 1, 0.5 the middle,
        and any other number a point that far along, inside the box or
        not. Holes stay where they are; a blind hole moves with the face it
        was drilled in, keeping its depth."""
        delta = value - self.size[axis]
        origin = np.asarray(self.origin) - anchor * delta * np.asarray(
            self.axes[axis])
        size = list(self.size)
        size[axis] = value
        return replace(self, origin=tuple(origin), size=tuple(size))

    def with_fillet(self, edge, radius: float):
        fillets = dict(self.fillets)
        if radius > 0:
            fillets[edge] = radius
        else:
            fillets.pop(edge, None)
        return replace(self, fillets=fillets)

    def with_chamfer(self, edge, distance: float):
        chamfers = dict(self.chamfers)
        if distance > 0:
            chamfers[edge] = distance
        else:
            chamfers.pop(edge, None)
        return replace(self, chamfers=chamfers)

    def with_hole(self, index: int, radius: float | None = None,
                  depth: float | None = None):
        holes = list(self.holes)
        if radius is not None and radius <= 0:
            del holes[index]
        else:
            hole = holes[index]
            holes[index] = replace(
                hole, radius=hole.radius if radius is None else radius,
                depth=hole.depth if depth is None else depth)
        return replace(self, holes=tuple(holes))


@dataclass(frozen=True)
class CylinderModel:
    """A cylinder: `base` the centre of the end it grows from, `axis` the
    unit vector towards the other end."""
    base: tuple
    axis: tuple
    radius: float
    height: float

    @property
    def axes(self):                  # what side_names() asks of a model
        return (self.axis,)

    def resized(self, value: float, anchor: float = 0.0):
        base = np.asarray(self.base) - anchor * (value - self.height) \
            * np.asarray(self.axis)
        return replace(self, base=tuple(base), height=value)


# --- reading ----------------------------------------------------------------

def read(shape, tolerance: float = 1e-6):
    """The BoxModel or CylinderModel a solid is, or NotRecognised."""
    from serpentine3d.core.geometry import shape_kind
    if shape_kind(shape) != "solid":
        raise NotRecognised("it is not a solid")
    faces = _faces(shape)
    scale = max([1.0] + [float(np.abs(f["point"]).max()) for f in faces])
    eps = max(tolerance, scale * _REL) * 10
    planes = [f for f in faces if f["kind"] == "plane"]
    rounds = [f for f in faces if f["kind"] == "cylinder"]
    if len(rounds) == 1 and len(planes) == 2 and len(faces) == 3:
        return _read_cylinder(shape, rounds[0], planes, scale, eps)
    reasons = []
    for axes in _square_triples(planes):
        try:
            model = _read_box(planes, rounds, axes, eps)
            _same_solid(shape, build(model), scale, eps)
            return model
        except NotRecognised as exc:
            reasons.append(str(exc))
    raise NotRecognised(reasons[0] if reasons else
                        "its flat faces do not face three square ways")


def _faces(shape):
    from OCP.BRepAdaptor import BRepAdaptor_Surface
    from OCP.GeomAbs import GeomAbs_SurfaceType
    from serpentine3d.core.geometry import faces_of, surface_area
    out = []
    for face in faces_of(shape):
        s = BRepAdaptor_Surface(face)
        kind = s.GetType()
        entry = {"face": face, "kind": "other", "point": np.zeros(3)}
        if kind == GeomAbs_SurfaceType.GeomAbs_Plane:
            ax = s.Plane().Axis()
            entry.update(kind="plane", normal=_vec(ax.Direction()),
                         point=_vec(ax.Location()),
                         area=surface_area(face))
        elif kind == GeomAbs_SurfaceType.GeomAbs_Cylinder:
            c = s.Cylinder()
            ax = c.Axis()
            entry.update(kind="cylinder", direction=_vec(ax.Direction()),
                         point=_vec(ax.Location()), radius=float(c.Radius()))
        out.append(entry)
    return out


def _vec(v):
    return np.array([v.X(), v.Y(), v.Z()], float)


def _parallel(a, b) -> bool:
    return abs(float(np.dot(a, b))) > _PARALLEL


def _square_triples(planes):
    """Three square directions the flat faces face, most area first, each
    right-handed and in the order that reads like x, y, z for a box drawn
    on the world. A chamfer faces a fourth way, and two chamfers on
    neighbouring edges can make a square triple of their own with the
    third side, so every triple is tried and the rebuild decides."""
    clusters = []                     # [direction, area]
    for p in planes:
        for c in clusters:
            if _parallel(p["normal"], c[0]):
                c[1] += p["area"]
                break
        else:
            clusters.append([p["normal"] / np.linalg.norm(p["normal"]),
                             p["area"]])
    triples = []
    for a, b, c in itertools.combinations(clusters, 3):
        if all(abs(float(np.dot(x[0], y[0]))) < _SQUARE
               for x, y in ((a, b), (a, c), (b, c))):
            triples.append((a[1] + b[1] + c[1], (a[0], b[0], c[0])))
    for _area, axes in sorted(triples, key=lambda t: -t[0]):
        yield _ordered(axes)


def _ordered(axes):
    world = np.eye(3)
    order = sorted(range(3), key=lambda i: int(np.argmax(np.abs(
        axes[i] @ world.T))))
    u, v = axes[order[0]], axes[order[1]]
    u = u if u[int(np.argmax(np.abs(u)))] > 0 else -u
    v = v if v[int(np.argmax(np.abs(v)))] > 0 else -v
    return u, v, np.cross(u, v)


def _read_box(planes, rounds, axes, eps) -> BoxModel:
    lows, highs = [], []
    for axis in axes:
        along = [float(np.dot(p["point"], axis)) for p in planes
                 if _parallel(p["normal"], axis)]
        if len(along) < 2:
            raise NotRecognised("its flat faces are not three pairs")
        lows.append(min(along))
        highs.append(max(along))
    size = tuple(h - lo for lo, h in zip(lows, highs))
    if min(size) <= eps:
        raise NotRecognised("it is flat")
    origin = sum(lo * a for lo, a in zip(lows, axes))
    model = BoxModel(tuple(float(c) for c in origin),
                     tuple(tuple(float(c) for c in a) for a in axes), size)
    chamfers = {}
    for p in planes:
        if any(_parallel(p["normal"], a) for a in axes):
            continue                  # a side, or the floor of a blind hole
        edge, distance = _chamfer_of(model, p["normal"], p["point"], eps)
        chamfers[edge] = distance
    fillets, holes = {}, []
    for c in rounds:
        edge = _edge_of_fillet(model, c["direction"], c["point"],
                               c["radius"], eps)
        if edge is not None:
            if edge in fillets and abs(fillets[edge] - c["radius"]) > eps:
                raise NotRecognised("an edge has two different fillets")
            fillets[edge] = c["radius"]
        else:
            holes.append(_hole_of(model, c, eps))
    return replace(model, fillets=fillets, chamfers=chamfers,
                   holes=tuple(holes))


def _local(model, point):
    return np.asarray(point, float) - np.asarray(model.origin)


def _edge_of_fillet(model, direction, point, radius, eps):
    """The box edge a cylinder rounds: its axis runs along one box axis and
    sits `radius` in from a face on each of the other two."""
    along = [i for i in range(3) if _parallel(direction, model.axes[i])]
    if len(along) != 1:
        return None
    a, b = (i for i in range(3) if i != along[0])
    local = _local(model, point)
    sides = []
    for axis in (a, b):
        t = float(np.dot(local, model.axes[axis]))
        if abs(t - radius) <= eps:
            sides.append(0)
        elif abs(t - (model.size[axis] - radius)) <= eps:
            sides.append(1)
        else:
            return None
    return (a, sides[0], b, sides[1])


def _chamfer_of(model, normal, point, eps):
    """The box edge a slanted flat face cuts, and how far back it cuts it.

    In each of the two faces it cuts, the distance in from the edge is
    where the slanted plane meets that face; both have to be the same, as
    the chamfer command makes them."""
    square = [i for i in range(3)
              if abs(float(np.dot(normal, model.axes[i]))) < _SQUARE]
    if len(square) != 1:
        raise NotRecognised("a flat face is neither a side nor a chamfer")
    a, b = (i for i in range(3) if i != square[0])
    na = float(np.dot(normal, model.axes[a]))
    nb = float(np.dot(normal, model.axes[b]))
    if abs(na) < _SQUARE or abs(nb) < _SQUARE:
        raise NotRecognised("a flat face is neither a side nor a chamfer")
    local = _local(model, point)
    pa = float(np.dot(local, model.axes[a]))
    pb = float(np.dot(local, model.axes[b]))
    # Which corner it cuts is told by where the face is, not by which way
    # its normal happens to point: measured in from each corner, the cut
    # line reaches both faces within the box only at the corner it cuts.
    for sa, sb in ((0, 0), (0, 1), (1, 0), (1, 1)):
        x = pa if sa == 0 else model.size[a] - pa
        y = pb if sb == 0 else model.size[b] - pb
        nx = na if sa == 0 else -na
        ny = nb if sb == 0 else -nb
        k = nx * x + ny * y
        reach_a, reach_b = k / nx, k / ny   # where it meets each face
        if eps < reach_a <= model.size[a] + eps \
                and eps < reach_b <= model.size[b] + eps:
            if abs(reach_a - reach_b) > eps:
                raise NotRecognised("a chamfer is not cut equally on both "
                                    "faces")
            return (a, sa, b, sb), (reach_a + reach_b) / 2
    raise NotRecognised("a flat face is neither a side nor a chamfer")


def _hole_of(model, c, eps) -> Hole:
    along = [i for i in range(3) if _parallel(c["direction"], model.axes[i])]
    if len(along) != 1:
        raise NotRecognised("a curved face is neither a fillet nor a hole")
    k = along[0]
    local = _local(model, c["point"])
    for other in range(3):
        if other != k:
            t = float(np.dot(local, model.axes[other]))
            if not c["radius"] < t < model.size[other] - c["radius"]:
                raise NotRecognised("a hole breaks out of the side of the "
                                    "box")
    reach = [float(np.dot(_local(model, p), model.axes[k]))
             for p in _vertices(c["face"])]
    t0, t1 = min(reach), max(reach)
    at_start, at_end = abs(t0) <= eps, abs(t1 - model.size[k]) <= eps
    point = tuple(float(x) for x in c["point"])
    if at_start and at_end:
        return Hole(k, point, c["radius"])
    if at_start:
        return Hole(k, point, c["radius"], side=0, depth=t1)
    if at_end:
        return Hole(k, point, c["radius"], side=1, depth=model.size[k] - t0)
    raise NotRecognised("a hole opens on neither side")


def _vertices(face):
    points = []
    exp = occ.TopExp_Explorer(face, occ.VERTEX)
    while exp.More():
        points.append(_vec(occ.point_of_vertex(occ.to_vertex(exp.Current()))))
        exp.Next()
    return points


def _read_cylinder(shape, side, planes, scale, eps) -> CylinderModel:
    axis = side["direction"] / np.linalg.norm(side["direction"])
    if not all(_parallel(p["normal"], axis) for p in planes):
        raise NotRecognised("its ends are not square to its side")
    if axis[int(np.argmax(np.abs(axis)))] < 0:
        axis = -axis                  # grows up, right or back, as drawn
    ends = sorted(float(np.dot(p["point"], axis)) for p in planes)
    on_axis = side["point"] - float(np.dot(side["point"], axis)) * axis
    model = CylinderModel(tuple(float(c) for c in on_axis + ends[0] * axis),
                          tuple(float(c) for c in axis), side["radius"],
                          ends[1] - ends[0])
    _same_solid(shape, build(model), scale, eps)
    return model


def _same_solid(shape, rebuilt, scale, eps):
    from serpentine3d.core.geometry import faces_of, volume
    if len(faces_of(shape)) != len(faces_of(rebuilt)):
        raise NotRecognised("it has faces its sizes do not explain")
    v0, v1 = abs(volume(shape)), abs(volume(rebuilt))
    if abs(v0 - v1) > max(v0, 1.0) * 1e-6 + eps * scale ** 2:
        raise NotRecognised("rebuilt from its sizes it comes out different")


# --- building ---------------------------------------------------------------

def build(model):
    if isinstance(model, CylinderModel):
        frame = occ.gp_Ax2(occ.gp_Pnt(*map(float, model.base)),
                           occ.gp_Dir(*map(float, model.axis)))
        return occ.BRepPrimAPI_MakeCylinder(frame, float(model.radius),
                                            float(model.height)).Shape()
    return _build_box(model)


def _build_box(model: BoxModel):
    """The box, then chamfers, then fillets, then holes."""
    from serpentine3d.core.geometry import GeometryError, boolean_difference, fillet_edges
    u, v, w = (np.asarray(a) for a in model.axes)
    frame = occ.gp_Ax2(occ.gp_Pnt(*map(float, model.origin)),
                       occ.gp_Dir(*map(float, w)), occ.gp_Dir(*map(float, u)))
    shape = occ.BRepPrimAPI_MakeBox(frame, *map(float, model.size)).Shape()
    for blends, chamfer in ((model.chamfers, True), (model.fillets, False)):
        if not blends:
            continue
        picked, sizes = _box_edges(model, shape, blends)
        shape = fillet_edges(shape, edges=picked, radii=sizes,
                             chamfer=chamfer)
    for hole in model.holes:
        shape = boolean_difference(shape, _drill(model, hole))
    if model.holes and not _is_one_solid(shape):
        raise GeometryError("a hole no longer fits in the box")
    return shape


def _box_edges(model, shape, blends):
    from serpentine3d.core.geometry import GeometryError, edges_of
    picked, sizes = [], []
    for edge in edges_of(shape):
        key = _edge_key(model, edge)
        if key in blends:
            picked.append(edge)
            sizes.append(float(blends[key]))
    if len(picked) != len(blends):
        raise GeometryError("a fillet or chamfer's edge is not on the box")
    return picked, sizes


def _edge_key(model, edge):
    """Which two faces a straight edge of the box lies on."""
    from OCP.BRepAdaptor import BRepAdaptor_Curve
    curve = BRepAdaptor_Curve(occ.to_edge(edge))
    halfway = (curve.FirstParameter() + curve.LastParameter()) / 2
    mid = _local(model, _vec(curve.Value(halfway)))
    on = []
    for axis in range(3):
        t = float(np.dot(mid, model.axes[axis])) / model.size[axis]
        if abs(t) < 1e-6:
            on.append((axis, 0))
        elif abs(t - 1) < 1e-6:
            on.append((axis, 1))
    if len(on) != 2:
        return None
    (a, sa), (b, sb) = sorted(on)
    return (a, sa, b, sb)


def _drill(model, hole: Hole):
    """The cutter for a hole: through, or from its face to its floor."""
    k = np.asarray(model.axes[hole.axis])
    on_axis = np.asarray(hole.point) - float(np.dot(
        _local(model, hole.point), k)) * k     # level with side 0
    size = model.size[hole.axis]
    if hole.through:
        start, direction, length = on_axis - _MARGIN * k, k, size + 2 * _MARGIN
    elif hole.side == 0:
        start, direction, length = on_axis - _MARGIN * k, k, \
            hole.depth + _MARGIN
    else:
        start, direction, length = on_axis + (size + _MARGIN) * k, -k, \
            hole.depth + _MARGIN
    frame = occ.gp_Ax2(occ.gp_Pnt(*map(float, start)),
                       occ.gp_Dir(*map(float, direction)))
    return occ.BRepPrimAPI_MakeCylinder(frame, float(hole.radius),
                                        float(length)).Shape()


def _is_one_solid(shape) -> bool:
    n = 0
    exp = occ.TopExp_Explorer(shape, occ.SOLID)
    while exp.More():
        n += 1
        exp.Next()
    return n == 1


# --- what a pick means ------------------------------------------------------

@dataclass(frozen=True)
class Pick:
    """What a picked edge or face stands for.

    `what` is "size" (along `axis`; `side` is the face picked, or -1 for an
    edge), "fillet" or "chamfer" (on `edge`), "hole" or "hole depth" (hole
    number `hole`), "diameter" or "height" (of a cylinder; `side` as for
    size)."""
    what: str
    axis: int = -1
    side: int = -1
    edge: tuple = ()
    hole: int = -1


def pick_of_edge(model, edge) -> Pick:
    from OCP.BRepAdaptor import BRepAdaptor_Curve
    from OCP.GeomAbs import GeomAbs_CurveType
    curve = BRepAdaptor_Curve(edge)
    kind = curve.GetType()
    if isinstance(model, CylinderModel):
        if kind == GeomAbs_CurveType.GeomAbs_Circle:
            return Pick("diameter")
        if kind == GeomAbs_CurveType.GeomAbs_Line:
            return Pick("height")
        raise NotRecognised("that edge is not one of the cylinder's")
    eps = max(model.size) * 1e-6
    if kind == GeomAbs_CurveType.GeomAbs_Line:
        line = curve.Line()
        d, p = _vec(line.Direction()), _vec(line.Location())
        hole = _hole_through(model, d, p, None, eps)
        if hole >= 0:
            return Pick("hole", hole=hole)
        for axis in range(3):
            if _parallel(d, model.axes[axis]):
                return Pick("size", axis=axis)
    if kind == GeomAbs_CurveType.GeomAbs_Circle:
        c = curve.Circle()
        d, p, r = (_vec(c.Axis().Direction()), _vec(c.Location()),
                   float(c.Radius()))
        key = _edge_of_fillet(model, d, p, r, eps)
        if key in model.fillets:
            return Pick("fillet", edge=key)
        hole = _hole_through(model, d, p, r, eps)
        if hole >= 0:
            return Pick("hole", hole=hole)
    raise NotRecognised("that edge is not a side, fillet or hole of the box")


def _hole_through(model, direction, point, radius, eps) -> int:
    """The hole whose wall or rim this is: same axis, and on its circle."""
    for i, hole in enumerate(model.holes):
        k = np.asarray(model.axes[hole.axis])
        if not _parallel(direction, k):
            continue
        off = np.asarray(point) - np.asarray(hole.point)
        off = off - float(np.dot(off, k)) * k
        gap = float(np.linalg.norm(off))
        if radius is None and abs(gap - hole.radius) <= eps:
            return i                  # a line on its wall
        if radius is not None and gap <= eps and \
                abs(radius - hole.radius) <= eps:
            return i                  # its rim
    return -1


def pick_of_face(model, face) -> Pick:
    from OCP.BRepAdaptor import BRepAdaptor_Surface
    from OCP.GeomAbs import GeomAbs_SurfaceType
    s = BRepAdaptor_Surface(face)
    kind = s.GetType()
    if isinstance(model, CylinderModel):
        if kind == GeomAbs_SurfaceType.GeomAbs_Cylinder:
            return Pick("diameter")
        if kind == GeomAbs_SurfaceType.GeomAbs_Plane:
            t = float(np.dot(_vec(s.Plane().Axis().Location())
                             - np.asarray(model.base), model.axis))
            return Pick("height",
                        side=0 if abs(t) <= model.height / 2 else 1)
        raise NotRecognised("that face is not one of the cylinder's")
    eps = max(model.size) * 1e-6
    if kind == GeomAbs_SurfaceType.GeomAbs_Plane:
        ax = s.Plane().Axis()
        normal, point = _vec(ax.Direction()), _vec(ax.Location())
        for axis in range(3):
            if _parallel(normal, model.axes[axis]):
                t = float(np.dot(_local(model, point), model.axes[axis]))
                if abs(t) <= eps:
                    return Pick("size", axis=axis, side=0)
                if abs(t - model.size[axis]) <= eps:
                    return Pick("size", axis=axis, side=1)
                for i, hole in enumerate(model.holes):
                    if hole.axis != axis or hole.through:
                        continue
                    floor = hole.depth if hole.side == 0 \
                        else model.size[axis] - hole.depth
                    if abs(t - floor) <= eps:
                        return Pick("hole depth", hole=i)
                raise NotRecognised("that flat face is not a side or a "
                                    "hole's floor")
        try:
            key, _distance = _chamfer_of(model, normal, point, eps)
        except NotRecognised:
            key = None
        if key in model.chamfers:
            return Pick("chamfer", edge=key)
    if kind == GeomAbs_SurfaceType.GeomAbs_Cylinder:
        c = s.Cylinder()
        d, p, r = (_vec(c.Axis().Direction()), _vec(c.Axis().Location()),
                   float(c.Radius()))
        key = _edge_of_fillet(model, d, p, r, eps)
        if key in model.fillets:
            return Pick("fillet", edge=key)
        hole = _hole_through(model, d, p + np.cross(d, _any_square(d)) * r,
                             None, eps)
        if hole >= 0:
            return Pick("hole", hole=hole)
    raise NotRecognised("that face is not a side, fillet, chamfer or hole "
                        "of the box")


def _any_square(d):
    helper = np.eye(3)[int(np.argmin(np.abs(d)))]
    v = np.cross(d, helper)
    return v / np.linalg.norm(v)


# --- naming -----------------------------------------------------------------

_SIDE_NAMES = (("Left", "Right"), ("Front", "Back"), ("Bottom", "Top"))


def side_names(model, axis: int) -> tuple:
    """What to call side 0 and side 1 along an axis: Bottom and Top along
    the world's Z, Left and Right along X, Front and Back along Y, the
    right way round even when the solid has been turned over; Start and
    End when the axis is not one of the world's."""
    a = np.asarray(model.axes[axis])
    i = int(np.argmax(np.abs(a)))
    if abs(a[i]) <= _PARALLEL:
        return ("Start", "End")
    low, high = _SIDE_NAMES[i]
    return (low, high) if a[i] > 0 else (high, low)


def _ends(model, axis: int):
    """Where side 0 and side 1 are along an axis: a point on each."""
    if isinstance(model, CylinderModel):
        base = np.asarray(model.base)
        return base, base + model.height * np.asarray(model.axis)
    a = np.asarray(model.axes[axis])
    o = np.asarray(model.origin)
    return o, o + model.size[axis] * a


def side_on_plane(model, axis: int, origin, normal,
                  tolerance: float = 1e-6):
    """0 or 1 if that side of the solid lies on the plane, else None: the
    side a solid drawn on the construction plane stands on."""
    n = np.asarray(normal, float)
    if not _parallel(n, model.axes[axis]):
        return None
    length = model.height if isinstance(model, CylinderModel) \
        else max(model.size)
    for side, point in enumerate(_ends(model, axis)):
        if abs(float(np.dot(point - np.asarray(origin, float), n))) \
                <= tolerance * max(1.0, length):
            return side
    return None


def anchor_at(model, axis: int, point) -> float:
    """Where a point sits along an axis, as resized() takes an anchor."""
    start, end = _ends(model, axis)
    length = float(np.linalg.norm(end - start))
    a = (end - start) / length
    return float(np.dot(np.asarray(point, float) - start, a)) / length


def axis_name(model, axis: int) -> str:
    """X, Y or Z when the solid lines up with the world, else 1st/2nd/3rd."""
    a = np.asarray(model.axes[axis])
    i = int(np.argmax(np.abs(a)))
    if abs(a[i]) > _PARALLEL:
        return "XYZ"[i]
    return ("first", "second", "third")[axis]


def describe(model, fmt=lambda x: f"{x:g}") -> str:
    if isinstance(model, CylinderModel):
        return (f"cylinder of diameter {fmt(2 * model.radius)}, "
                f"{fmt(model.height)} high")
    parts = ["box " + " x ".join(fmt(s) for s in model.size)]
    for label, blends in (("fillet", model.fillets),
                          ("chamfer", model.chamfers)):
        if blends:
            sizes = ", ".join(fmt(r) for r in
                              sorted(set(round(r, 9)
                                         for r in blends.values())))
            parts.append(f"{len(blends)} {label}(s) of {sizes}")
    if model.holes:
        parts.append(f"{len(model.holes)} hole(s)")
    return ", ".join(parts)

import sys

from serpentine3d.core import geometry as g


def serpentine3d_plugin(ctx):
    command = ctx.command

    @command("editdimension")
    def cmd_editdimension(ctx):
        """Show and change a size, fillet, chamfer or hole from a picked edge.

        Ctrl+Shift-click one edge or face first. On a box: a straight edge gives
        its length along it, a flat face the distance to the face across, a
        fillet or chamfer its size, a hole its diameter and a blind hole's floor
        its depth. On a cylinder: its round side or edge gives the diameter, an
        end or straight edge the height. A length first asks for the point that
        stays put: click one, choose a side, or press Enter for the one offered
        (the side on the construction plane, or the face across from a picked
        face). The solid is rebuilt with everything else as it was: fillets
        keep their radius when a box grows, and holes stay where they are. Works
        on any such solid, however it was drawn, moved or imported."""
        sd = sys.modules[__name__]
        from serpentine3d.commands.base import NumberReq, PointReq
        held = list(ctx.selection.subobjects)
        if len(held) != 1:
            ctx.echo("Ctrl+Shift-click one edge or face first: a side gives its "
                     "size, a fillet, chamfer or hole its own.")
            return
        obj_id, kind, index = held[0]
        obj = ctx.scene.get(obj_id)
        if obj is None:
            return
        try:
            model = sd.read(obj.shape)
            if kind == "edge":
                pick = sd.pick_of_edge(model, g.edges_of(obj.shape)[index])
            else:
                pick = sd.pick_of_face(model, g.faces_of(obj.shape)[index])
        except sd.NotRecognised as exc:
            ctx.echo(f"{obj.name} has no dimensions to edit here: {exc}.")
            return
        fmt = ctx.scene.format_length
        ctx.echo(f"{obj.name}: {sd.describe(model, fmt)}.")

        if pick.what in ("size", "height"):
            axis = pick.axis if pick.what == "size" else 0
            # What stays put is asked every time, with an answer ready for
            # Enter: the face across from a picked face, else the side standing
            # on the construction plane, else the low side.
            names = sd.side_names(model, axis)
            if pick.side >= 0:
                held_side = 1 - pick.side
            else:
                on = sd.side_on_plane(model, axis, ctx.cplane.origin,
                                      ctx.cplane.normal)
                held_side = 0 if on is None else on
            offered = names[held_side]
            anchor = yield PointReq(
                f"Point that stays put (Enter for the {offered.lower()})",
                allow_empty=True, extra_options=(names[0], "Middle", names[1]))
            if anchor is None:
                anchor = offered
            if isinstance(anchor, str):
                fraction = {names[0]: 0.0, "Middle": 0.5, names[1]: 1.0}[anchor]
                where = f"the {anchor.lower()}"
            else:
                fraction = sd.anchor_at(model, axis, anchor)
                where = "the picked point"
            if pick.what == "size":
                label = f"Size along {sd.axis_name(model, axis)}"
                current = model.size[axis]
            else:
                label = "Height"
                current = model.height
            value = yield NumberReq(label, default=current, minimum=0)
            if value <= 0:
                ctx.echo("A size has to be above zero.")
                return
            new = (model.resized(axis, value, fraction) if pick.what == "size"
                   else model.resized(value, fraction))
            label = f"{label}, held at {where}"
        elif pick.what == "diameter":
            label = "Diameter"
            current = 2 * model.radius
            value = yield NumberReq(label, default=current, minimum=0)
            if value <= 0:
                ctx.echo("A diameter has to be above zero.")
                return
            new = sd.CylinderModel(model.base, model.axis, value / 2,
                                   model.height)
        elif pick.what == "fillet":
            label = "Fillet radius"
            current = model.fillets[pick.edge]
            value = yield NumberReq(f"{label} (0 removes it)", default=current,
                                    minimum=0)
            new = model.with_fillet(pick.edge, value)
        elif pick.what == "chamfer":
            label = "Chamfer distance"
            current = model.chamfers[pick.edge]
            value = yield NumberReq(f"{label} (0 removes it)", default=current,
                                    minimum=0)
            new = model.with_chamfer(pick.edge, value)
        elif pick.what == "hole":
            label = "Hole diameter"
            current = 2 * model.holes[pick.hole].radius
            value = yield NumberReq(f"{label} (0 fills it)", default=current,
                                    minimum=0)
            new = model.with_hole(pick.hole, radius=value / 2)
        else:                                       # a blind hole's floor
            label = "Hole depth"
            current = model.holes[pick.hole].depth
            value = yield NumberReq(label, default=current, minimum=0)
            if value <= 0:
                ctx.echo("A hole has to go in some way; pick its wall and give "
                         "0 to fill it.")
                return
            new = model.with_hole(pick.hole, depth=value)
        try:
            shape = sd.build(new)
        except g.GeometryError as exc:
            ctx.echo(f"{obj.name}: {exc}. Nothing changed.")
            return
        ctx.scene.replace_shape(obj_id, shape)
        ctx.selection.clear()          # the picked index means another edge now
        ctx.echo(f"{label}: {fmt(current)} → {fmt(value)}.")
